{
  "hypotheses": [
    {
      "name": "Organizational Creativity Premium",
      "mechanism": "Firms that simultaneously invest in organizational capital (OrgCap) and brand capital (BrandInvest), while showing a high ratio of patents to R&D (PatentsRD), reflect a nexus of creativity and implementation ability. The composite exploits the interaction between creative output and the ability to commercialize innovation, which should yield excess returns due to market underestimation of intangible synergy.",
      "expression": {
        "terms": [
          {"weight": 0.5, "primitive": "OrgCap"},
          {"weight": 0.5, "primitive": "BrandInvest"},
          {"weight": 1.0, "primitive": "PatentsRD"}
        ],
        "regime": "MKT_TRAILING_12M_UP",
        "vol_target": true
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
        {"type": "correlation", "primitive": "OrgCap", "bound": "below", "threshold": 0.3},
        {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
      ],
      "expected_annualized_sharpe": 0.7,
      "expected_decay_half_life_months": 48
    },
    {
      "name": "Attention Scarcity Composite",
      "mechanism": "Stocks with low analyst coverage drops (ChNAnalyst), high trading frictions (BidAskSpread), and high probability of informed trading (ProbInformedTrading) are neglected by the market. Their mispricing is amplified when they also have large order backlogs (OrderBacklog), which rarely attract attention until resolved. The composite captures the premium from the market’s underreaction to hard-to-observe news.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "ChNAnalyst"},
          {"weight": 0.5, "primitive": "BidAskSpread"},
          {"weight": 0.5, "primitive": "ProbInformedTrading"},
          {"weight": 1.0, "primitive": "OrderBacklog"}
        ],
        "regime": "VIX_ABOVE_TRAILING_MEDIAN",
        "vol_target": false
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
        {"type": "size_segment", "segment": "micro", "direction": "stronger"},
        {"type": "subperiod_consistency"}
      ],
      "expected_annualized_sharpe": 0.62,
      "expected_decay_half_life_months": 24
    },
    {
      "name": "Real Asset Duration Anomaly",
      "mechanism": "A blend of real estate holdings (realestate), equity duration (EquityDuration), and net payout yield (NetPayoutYield) isolates firms whose return profiles are linked to the value of long-duration real assets and shareholder distributions. The interaction exploits structural underpricing of long-term, tangible asset-backed cash flows, especially during low term premia.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "realestate"},
          {"weight": 0.5, "primitive": "EquityDuration"},
          {"weight": -0.5, "primitive": "NetPayoutYield"}
        ],
        "regime": "TERM_SPREAD_NEGATIVE",
        "vol_target": true
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
        {"type": "size_segment", "segment": "large", "direction": "stronger"},
        {"type": "international", "region": "emerging", "direction": "same_sign"}
      ],
      "expected_annualized_sharpe": 0.55,
      "expected_decay_half_life_months": 60
    },
    {
      "name": "Volatility-Driven Customer Friction",
      "mechanism": "Combining customer momentum (CustomerMomentum), realized volatility (RealizedVol), and Amihud illiquidity (Illiquidity) captures companies whose stock volatility signals underlying demand instability, but where customer-related earnings momentum is persistent. The interaction arises because volatility-driven price drops may obscure underlying customer traction and create mispricing.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "CustomerMomentum"},
          {"weight": -0.5, "primitive": "RealizedVol"},
          {"weight": 0.5, "primitive": "Illiquidity"}
        ],
        "regime": "MKT_TRAILING_12M_DOWN",
        "vol_target": false
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
        {"type": "size_segment", "segment": "small", "direction": "stronger"},
        {"type": "correlation", "primitive": "CustomerMomentum", "bound": "below", "threshold": 0.3}
      ],
      "expected_annualized_sharpe": 0.58,
      "expected_decay_half_life_months": 30
    },
    {
      "name": "Intangible Franchise Synergy",
      "mechanism": "Firms with high advertising expense growth (GrAdExp), high R&D over market cap (RD), and high analyst optimism (AOP) combine brand-building, innovation, and collective optimism. The composite exploits the market’s underreaction to the compounded effects of intangible franchise development, especially when these signals align.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "GrAdExp"},
          {"weight": 0.5, "primitive": "RD"},
          {"weight": 1.0, "primitive": "AOP"}
        ],
        "regime": null,
        "vol_target": true
      },
      "auxiliary_predictions": [
        {"type": "size_segment", "segment": "large", "direction": "stronger"},
        {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
        {"type": "subperiod_consistency"}
      ],
      "expected_annualized_sharpe": 0.65,
      "expected_decay_half_life_months": 36
    },
    {
      "name": "Countercyclical Labor Leverage",
      "mechanism": "By blending employment growth (hire), operating leverage (OPLeverage), and deferred revenue (DelDRC), this composite captures firms that expand labor during downturns and utilize deferred revenue for operational flexibility. These firms benefit from cost absorption and future revenue, which markets underappreciate when growth is generally scarce.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "hire"},
          {"weight": 0.5, "primitive": "OPLeverage"},
          {"weight": 0.5, "primitive": "DelDRC"}
        ],
        "regime": "MKT_TRAILING_12M_DOWN",
        "vol_target": true
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
        {"type": "size_segment", "segment": "large", "direction": "stronger"},
        {"type": "correlation", "primitive": "hire", "bound": "below", "threshold": 0.3}
      ],
      "expected_annualized_sharpe": 0.6,
      "expected_decay_half_life_months": 18
    },
    {
      "name": "Market Neglect and ESG Risk Transfer",
      "mechanism": "A mix of sin stock selection (sinAlgo), excluded expenses (ExclExp), and governance index (Governance) isolates firms with controversial exposures and aggressive accounting, but that paradoxically score well on governance metrics. This composite captures pricing distortions arising from sustainable investing mandates and market neglect of complex ESG tradeoffs.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "sinAlgo"},
          {"weight": 0.5, "primitive": "ExclExp"},
          {"weight": 1.0, "primitive": "Governance"}
        ],
        "regime": "VIX_BELOW_TRAILING_MEDIAN",
        "vol_target": false
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
        {"type": "size_segment", "segment": "mega", "direction": "stronger"},
        {"type": "international", "region": "emerging", "direction": "opposite_sign"}
      ],
      "expected_annualized_sharpe": 0.53,
      "expected_decay_half_life_months": 12
    },
    {
      "name": "Revenue Quality Contrarian",
      "mechanism": "Firms with positive earnings forecast revisions (REV6), low percentage of total accruals (PctTotAcc), and high order backlog changes (OrderBacklogChg) are likely experiencing quality revenue growth the market wrongly fades after negative aggregate sentiment. The composite exploits the market’s tendency to extrapolate negative news despite improving micro-fundamentals.",
      "expression": {
        "terms": [
          {"weight": 1.0, "primitive": "REV6"},
          {"weight": -0.5, "primitive": "PctTotAcc"},
          {"weight": 1.0, "primitive": "OrderBacklogChg"}
        ],
        "regime": "TERM_SPREAD_POSITIVE",
        "vol_target": false
      },
      "auxiliary_predictions": [
        {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
        {"type": "size_segment", "segment": "small", "direction": "stronger"},
        {"type": "correlation", "primitive": "REV6", "bound": "below", "threshold": 0.3}
      ],
      "expected_annualized_sharpe": 0.56,
      "expected_decay_half_life_months": 24
    }
  ]
}
